using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.SGR.Perfiles;namespace GraphApi.Services.SGR.Perfiles{    public class PerfilesService : IPerfilesService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public PerfilesService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadPerfiles>> GetPerfiles(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM sgr.vsPerfiles (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadPerfiles>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetPerfilesDynamic(            int? perfilID,            string? perfil,            string? descripcion,            bool? bAdministrador,            bool? bEliminado,            int? usuariosAsignados,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "PerfilID, Perfil, Descripcion, bAdministrador, bEliminado, UsuariosAsignados" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM sgr.vsPerfiles (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (perfilID.HasValue)            {                vSql.Append(" AND PerfilID = @PerfilID");                vParameters.Add("PerfilID",perfilID);            }            if (!string.IsNullOrWhiteSpace(perfil))            {                vSql.Append(" AND Perfil LIKE @Perfil");                vParameters.Add("Perfil",$"%{perfil}%");            }            if (!string.IsNullOrWhiteSpace(descripcion))            {                vSql.Append(" AND Descripcion LIKE @Descripcion");                vParameters.Add("Descripcion",$"%{descripcion}%");            }            if (bAdministrador.HasValue)            {                vSql.Append(" AND bAdministrador = @bAdministrador");                vParameters.Add("bAdministrador", bAdministrador.Value);            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadPerfiles> CreatePerfiles(clCreatePerfiles objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO sgr.Perfiles                (Perfil, Descripcion, bEliminado, bAdministrador, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@Perfil, @Descripcion, @bEliminado, @bAdministrador, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.Perfil,                objInput.Descripcion,                objInput.bEliminado,                objInput.bAdministrador,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT PerfilID, Perfil, Descripcion, bAdministrador, bEliminado, UsuariosAsignados                FROM sgr.vsPerfiles (NOLOCK)                WHERE PerfilID = @PerfilID;";            var vReadParams = new { PerfilID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadPerfiles>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el Perfile con ID {vNewId}.");            return vCreated;        }        public async Task<clReadPerfiles?> UpdatePerfiles(clUpdatePerfiles objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("PerfilID", objInput.PerfilID);            if (objInput.Perfil is not null)            {                vSets.Add("Perfil = @Perfil");                vParameters.Add("Perfil", objInput.Perfil);            }            if (objInput.Descripcion is not null)            {                vSets.Add("Descripcion = @Descripcion");                vParameters.Add("Descripcion", objInput.Descripcion);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            if (objInput.bAdministrador != null)            {                vSets.Add("bAdministrador = @bAdministrador");                vParameters.Add("bAdministrador", objInput.bAdministrador);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE sgr.Perfiles                SET {vSetClause}                WHERE PerfilID = @PerfilID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT PerfilID, Perfil, Descripcion, bAdministrador, bEliminado, UsuariosAsignados                FROM sgr.vsPerfiles (NOLOCK)                WHERE PerfilID = @PerfilID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadPerfiles>(sSelect, new {  objInput.PerfilID });        }        public async Task<bool> DeletePerfiles(int nPerfilesID)        {            const string sSql = @"                DELETE FROM sgr.Perfiles                WHERE PerfilID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nPerfilesID });            return vAffected > 0;        }    }}